// Author: MiYu. Deferred live consumers for source aura membership, inventory providers and real weapon passives.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_passive_tests <data-root> <generated-passive-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession s(jass::Module::compile(jass::Program::read(archives)),info);s.attachWorld(std::move(world));s.audioMuted(true);s.configure();PlayerSetup setup(info,s.config());s.applySetup(setup);s.startMain();auto& vm=s.runtime();
        auto check=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto real=[](float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));};auto number=[](jass::Real v){return std::bit_cast<float>(v.bits());};auto code=[&](const char* id){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(id)));};auto bounds=s.world()->bounds();auto x=bounds.minX.add(bounds.maxX).divide(jass::Real::fromInteger(2)),y=bounds.minY.add(bounds.maxY).divide(jass::Real::fromInteger(2));
        vm.invoke("FogEnable",std::array{vm.boolean(false)});vm.invoke("FogMaskEnable",std::array{vm.boolean(false)});
        auto create=[&](unsigned owner,const char* type,float offset){auto h=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),code(type),vm.real(x.add(real(offset))),vm.real(y),vm.real(real(0))});vm.invoke("SetUnitPathing",std::array{h,vm.boolean(false)});auto u=s.units().at(h.bits);u->healthRegen=u->manaRegen=0;u->acquireRange={};u->maxLife=real(10000);u->life=u->maxLife;u->maxMana=real(1000);u->mana={};s.stopUnit(h.bits);return h;};auto add=[&](jass::Value u,const char* ability){check(vm.invoke("UnitAddAbility",std::array{u,code(ability)}).bits!=0,"Source ability add failed");};auto remove=[&](jass::Value u,const char* ability){vm.invoke("UnitRemoveAbility",std::array{u,code(ability)});};
        auto provider=create(0,"Hpal",0),strong=create(0,"Hpal",50),recipient=create(0,"hfoo",100),enemy=create(1,"hfoo",150);auto p=s.units().at(provider.bits),r=s.units().at(recipient.bits),e=s.units().at(enemy.bits);auto buttons=s.abilityCommands(provider.bits,0,true);check(std::any_of(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("AHad") && b.enabled;}),"Passive learning button incorrectly disabled");check(s.learnHeroSkill(provider.bits,ObjectData::code("AHad")),"Devotion learning rejected");s.advance(.0625);check(std::abs(r->aura.armor-1.5f)<.001f && e->aura.armor==0 && vm.invoke("GetUnitAbilityLevel",std::array{recipient,code("BHad")}).bits==1,"Aura relationship/value/query missing");auto uiWeak=s.unitCombatDisplay(recipient.bits);check(uiWeak && uiWeak->weapons[0].enabled && uiWeak->weapons[0].minimum<=uiWeak->weapons[0].maximum,"Unit combat display lacks weapon bounds");buttons=s.abilityCommands(provider.bits,0);check(std::any_of(buttons.begin(),buttons.end(),[](auto& b){return b.type==ObjectData::code("AHad") && b.action==CommandAction::PassiveSkill && b.enabled;}),"Passive command consumer missing");
        add(strong,"AHad");vm.invoke("SetUnitAbilityLevel",std::array{strong,code("AHad"),vm.integer(3)});s.advance(.25);check(std::abs(r->aura.armor-4.5f)<.001f && r->auras.at(ObjectData::code("BHad")).source==strong.bits,"Shared buff did not select strongest source");auto uiStrong=s.unitCombatDisplay(recipient.bits);check(uiStrong && std::abs(uiStrong->armor-uiWeak->armor-3.f)<.001f,"Unit combat display did not consume changed armor aura");remove(strong,"AHad");s.advance(.25);check(std::abs(r->aura.armor-1.5f)<.001f,"Aura did not fall back to remaining source");vm.invoke("SetUnitX",std::array{provider,vm.real(x.add(real(-2000)))});s.advance(.25);check(r->aura.armor>0,"Aura retention disappeared immediately");s.advance(2.25);check(r->aura.armor==0 && !r->auras.contains(ObjectData::code("BHad")),"Out-of-range aura did not expire");vm.invoke("SetUnitX",std::array{provider,vm.real(x)});
        for(auto ability:{"AHab","AOae","AUau","AUav","AEar","AEah","ACac","Aakb","Aoar"})add(provider,ability);r->life=real(1000);r->mana={};s.advance(.25);check(std::abs(r->aura.movement-.2f)<.001f && std::abs(r->aura.attackSpeed-.05f)<.001f && std::abs(r->aura.meleeDamage-.2f)<.001f && std::abs(r->aura.rangedDamage-.3f)<.001f,"Aura movement/speed/weapon masks missing");auto uiDamage=s.unitCombatDisplay(recipient.bits);check(uiDamage && uiDamage->weapons[0].maximum>uiWeak->weapons[0].maximum,"Unit combat display did not consume melee damage aura");check(std::abs(r->aura.vampiric-.15f)<.001f && std::abs(r->aura.thorns-.1f)<.001f,"Aura combat modifiers missing");auto life=number(r->life),mana=number(r->mana);s.advance(1);check(number(r->life)>life+190 && number(r->mana)>mana+.7f,"Aura regeneration not consumed");unsigned shared=0;for(auto& [id,fx]:s.effects())if(fx->target==recipient.bits && !fx->destroyed && fx->model.find("GeneralAuraTarget")!=std::string::npos)++shared;check(shared==1,"Identical recipient aura visuals were duplicated");
        auto selection=std::array{recipient,vm.boolean(true),vm.boolean(false),vm.boolean(true),vm.boolean(false),vm.boolean(false),vm.boolean(true),vm.boolean(false)};check(vm.invoke("UnitCountBuffsEx",selection).bits>=10,"Aura selection not exposed in buff query");vm.invoke("UnitRemoveBuffsEx",selection);check(r->auras.empty() && r->aura.armor==0 && r->auraVisuals.empty(),"Explicit aura removal retained state or visuals");s.advance(.25);check(!r->auras.empty(),"Live emitter did not reapply removed aura");
        auto carrier=create(0,"Hpal",2000),itemRecipient=create(0,"hfoo",2050);auto item=vm.invoke("UnitAddItemById",std::array{carrier,code("sbch")});check(item.bits!=0,"Source aura item missing");s.advance(.25);check(s.units().at(itemRecipient.bits)->aura.vampiric>0,"Inventory aura ability not consumed");s.dropItem(carrier.bits,item.bits);s.advance(2.5);check(s.units().at(itemRecipient.bits)->aura.vampiric==0,"Dropped item kept emitting");
        auto attacker=create(0,"hfoo",3000),victim=create(1,"hfoo",3060),side=create(1,"hfoo",3160),friendSide=create(0,"hfoo",3180);auto a=s.units().at(attacker.bits),v=s.units().at(victim.bits);auto strike=[&]{s.stopUnit(attacker.bits);s.advance(2.5);v->life=v->maxLife;float before=number(v->life);check(s.attackUnit(attacker.bits,victim.bits),"Actual weapon order rejected");s.advance(.75);s.stopUnit(attacker.bits);return before-number(v->life);};float ordinary=strike();check(ordinary>0,"Baseline attack did not hit");add(attacker,"A0CR");check(strike()>ordinary*1.7f,"Critical multiplier did not reach weapon damage");remove(attacker,"A0CR");vm.invoke("SetRandomSeed",std::array{vm.integer(17)});add(attacker,"AOcr");for(auto expected:{2u,3u,4u,1u,2u,3u,4u,5u}){strike();check(a->criticalFailures.contains(ObjectData::code("AOcr")) && a->criticalFailures.at(ObjectData::code("AOcr"))==expected,"Critical pseudo-random state differs from source sequence");}remove(attacker,"AOcr");check(!a->criticalFailures.contains(ObjectData::code("AOcr")),"Removed critical ability retained pseudo-random state");add(victim,"A0EV");check(strike()==0,"Full evasion allowed primary hit");add(attacker,"A0NM");check(strike()>0,"Never-miss critical did not bypass evasion");remove(attacker,"A0NM");remove(victim,"A0EV");add(attacker,"A0BH");check(strike()>ordinary*2 && v->stunned() && v->buffs.at(ObjectData::code("BPSE")).physical,"Bash bonus/stun/physical state missing");remove(attacker,"A0BH");remove(victim,"BPSE");add(attacker,"ANca");auto sideLife=number(s.units().at(side.bits)->life),friendLife=number(s.units().at(friendSide.bits)->life);strike();check(number(s.units().at(side.bits)->life)<sideLife && number(s.units().at(friendSide.bits)->life)==friendLife,"Cleave radius/relationship missing");remove(attacker,"ANca");
        add(attacker,"AUav");a->life=real(1000);life=number(a->life);strike();check(number(a->life)>life,"Melee life steal did not heal actual attacker");remove(attacker,"AUav");s.advance(2.5);add(victim,"AEah");a->life=real(1000);life=number(a->life);strike();check(number(a->life)<life,"Thorns did not reflect melee hit");vm.invoke("KillUnit",std::array{victim});check(v->auras.empty() && v->auraVisuals.empty(),"Death retained recipient aura state");
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS passive consumers: learning, strongest aura, expiry, source stats, shared visuals, inventory, critical/evasion/bash/cleave and melee effects\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
